import { useState, useCallback } from 'react';
import { Button, Modal, Stack, Text } from '@jinx-ui/react';

export type DeleteProjectDialogProps = {
  onConfirm: () => void;
  projectName?: string;
  disabled?: boolean;
};

export default function DeleteProjectDialog({
  onConfirm,
  projectName,
  disabled = false,
}: DeleteProjectDialogProps) {
  const [isOpen, setIsOpen] = useState(false);

  const open = useCallback(() => setIsOpen(true), []);
  const close = useCallback(() => setIsOpen(false), []);

  const confirm = useCallback(() => {
    setIsOpen(false);
    onConfirm();
  }, [onConfirm]);

  return (
    <>
      <Button variant="danger" disabled={disabled} onClick={open}>
        Удалить проект
      </Button>

      <Modal
        open={isOpen}
        onClose={close}
        title="Удалить проект?"
        aria-labelledby="delete-project-title"
      >
        <Stack direction="column" gap="var(--jx-space-4)">
          <Text tone="muted">
            {projectName
              ? `Проект «${projectName}» и все его данные будут удалены безвозвратно. Действие необратимо.`
              : 'Проект и все его данные будут удалены безвозвратно. Действие необратимо.'}
          </Text>

          <Stack direction="row" gap="var(--jx-space-2)" justify="end">
            <Button variant="secondary" onClick={close}>
              Отмена
            </Button>
            <Button variant="danger" onClick={confirm} autoFocus>
              Удалить
            </Button>
          </Stack>
        </Stack>
      </Modal>
    </>
  );
}

